import marimo

__generated_with = "0.24.0"
app = marimo.App(width="medium")


@app.cell
def _():
    import marimo as mo
    import duckdb
    import pathlib
    import altair as alt
    return alt, duckdb, mo, pathlib


@app.cell
def _(mo):
    mo.md(
        r"""
        # DAR — Regional revenue

        ## Business question

        **Which region generated the most revenue in H1, and how did it move
        month over month?**

        Answered directly from `dar__uss.stg_sales` in the shared DuckDB
        warehouse. Nothing is copied into the notebook.
        """
    )
    return


@app.cell
def _(duckdb, pathlib):
    DB = pathlib.Path(__file__).parent / "warehouse.duckdb"
    con = duckdb.connect(str(DB), read_only=True)
    return (con,)


@app.cell
def _(con):
    answer = con.execute(
        """
        SELECT region,
               CAST(SUM(revenue) AS DOUBLE) AS revenue,
               SUM(orders)                  AS orders
        FROM dar__uss.stg_sales
        GROUP BY 1
        ORDER BY revenue DESC
        """
    ).pl()
    answer
    return (answer,)


@app.cell
def _(answer, mo):
    top = answer.row(0, named=True)
    mo.md(
        f"""
        ### Answer

        **{top['region']}** leads with **{top['revenue']:,.2f}** across
        **{top['orders']}** orders.
        """
    )
    return


@app.cell
def _(alt, answer, mo):
    bar = (
        alt.Chart(answer)
        .mark_bar()
        .encode(
            x=alt.X("region:N", sort="-y", title="Region"),
            y=alt.Y("revenue:Q", title="Revenue"),
            color=alt.Color("region:N", legend=None),
        )
        .properties(width=420, height=240, title="Revenue by region (altair)")
    )
    chart = mo.ui.altair_chart(bar)
    chart
    return


@app.cell
def _(con):
    trend = con.execute(
        """
        SELECT region, month, CAST(revenue AS DOUBLE) AS revenue
        FROM dar__uss.stg_sales ORDER BY region, month
        """
    ).pl()
    return (trend,)


@app.cell
def _(alt, trend):
    alt.Chart(trend).mark_line(point=True).encode(
        x="month:T", y="revenue:Q", color="region:N"
    ).properties(width=420, height=200, title="Month over month (altair, plain)")
    return


@app.cell
def _(answer):
    import plotly.express as px

    px.bar(
        answer.to_pandas() if hasattr(answer, "to_pandas") else answer,
        x="region", y="revenue", title="Revenue by region (plotly)",
    )
    return


@app.cell
def _(answer):
    import matplotlib.pyplot as plt

    fig, ax = plt.subplots(figsize=(5, 2.5))
    ax.bar(answer["region"].to_list(), answer["revenue"].to_list())
    ax.set_title("Revenue by region (matplotlib)")
    ax
    return


if __name__ == "__main__":
    app.run()
PYEOF
